+import {createChatOrchestrator} from './chatOrchestrator.js';
+import {writeSignalPromptBuilder} from '../infrastructure/writeSignalTestSupport.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+
+const probeRejection = async (thrown: unknown) => {
+  let reported: Error | undefined;
+  const provider: AIProvider = {
+    // eslint-disable-next-line require-yield
+    async *sendMessage(): AsyncGenerator<MessageChunk> {
+      throw thrown;
+    },
+    generateStructured: async <T>() => ({}) as T,
+  };
+  const session: ChatSession = {
+    sessionId: 's-wrap',
+    userId: 'u-wrap',
+    entries: [{role: 'user', content: 'ping', timestamp: '2026-01-01T00:00:00.000Z'}],
+  };
+  const orchestrator = createChatOrchestrator(provider, writeSignalPromptBuilder, undefined, {
+    hooks: {
+      onError: async (_session, hookError) => {
+        reported = hookError;
+      },
+    },
+  });
+  const caught = await orchestrator.processMessage(session).then(
+    reply => ({ok: true, value: reply as unknown}),
+    (reason: unknown) => ({ok: false, value: reason})
+  );
+  return {
+    caught,
+    reported,
+    isError: reported instanceof Error,
+    message: reported?.message,
+    cause: reported?.cause,
+    hasCause: reported !== undefined ? Object.hasOwn(reported, 'cause') : false,
+  };
+};
+
+describe('ChatOrchestrator onError coercion', () => {
+  it('wraps a thrown string, plain object, or undefined in an Error with cause while passing an Error instance through', async () => {
+    const existingError = new Error('already an Error');
+    const upstreamBody = {status: 502, detail: 'bad gateway'};
+
+    const [fromString, fromObject, fromBareThrow, fromError] = await Promise.all([
+      probeRejection('raw string'),
+      probeRejection(upstreamBody),
+      probeRejection(undefined),
+      probeRejection(existingError),
+    ]);
+
+    expect({
+      string: {
+        caught: fromString.caught,
+        isError: fromString.isError,
+        message: fromString.message,
+        cause: fromString.cause,
+      },
+      object: {
+        caught: fromObject.caught,
+        isError: fromObject.isError,
+        mentionsDetail: fromObject.message?.includes('bad gateway') ?? false,
+        cause: fromObject.cause,
+      },
+      bareThrow: {
+        caught: fromBareThrow.caught,
+        isError: fromBareThrow.isError,
+        hasMessage: (fromBareThrow.message?.length ?? 0) > 0,
+        hasCause: fromBareThrow.hasCause,
+        cause: fromBareThrow.cause,
+      },
+      errorInstance: {
+        caught: fromError.caught,
+        sameInstance: fromError.reported === existingError,
+      },
+    }).toEqual({
+      string: {caught: {ok: false, value: 'raw string'}, isError: true, message: 'raw string', cause: 'raw string'},
+      object: {caught: {ok: false, value: upstreamBody}, isError: true, mentionsDetail: true, cause: upstreamBody},
+      bareThrow: {
+        caught: {ok: false, value: undefined},
+        isError: true,
+        hasMessage: true,
+        hasCause: true,
+        cause: undefined,
+      },
+      errorInstance: {caught: {ok: false, value: existingError}, sameInstance: true},
+    });
+  });
+});

